# Load all grids from this session
import os, re

def load():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    sessions_file = '/home/USER/runs/paper/qwen-h0c1-card/frozen/seen-reference-3/play/users/u027/system/state/sessions/' + os.path.basename(d) + '.jsonl'
    try:
        with open(sessions_file, 'r') as f:
            content = f.read()
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in content[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        return G
    except:
        return {}

G = load()
print("Loaded grids:", list(G.keys()))
for k, v in G.items():
    print(f"  {k}: {v}")

